using System;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        int i = 0;

        if (Vector512.IsHardwareAccelerated && data.Length >= Vector512<int>.Count)
        {
            var vThreshold = Vector512.Create(threshold);
            var vOne = Vector512.Create(1);
            ref int start = ref MemoryMarshal.GetReference(data);

            int lastVector = data.Length - Vector512<int>.Count;
            for (; i <= lastVector; i += Vector512<int>.Count)
            {
                var vec = Vector512.LoadUnsafe(ref start, (nuint)i);
                // CompareGreaterThan produces all-ones (-1) mask per element where vec > threshold
                var mask = Vector512.GreaterThan(vec, vThreshold);
                // Subtract mask (-1 becomes +1) to conditionally increment
                vec = Vector512.Subtract(vec, mask);
                Vector512.StoreUnsafe(vec, ref start, (nuint)i);
            }
        }
        else if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<int>.Count)
        {
            var vThreshold = Vector256.Create(threshold);
            ref int start = ref MemoryMarshal.GetReference(data);

            int lastVector = data.Length - Vector256<int>.Count;
            for (; i <= lastVector; i += Vector256<int>.Count)
            {
                var vec = Vector256.LoadUnsafe(ref start, (nuint)i);
                var mask = Vector256.GreaterThan(vec, vThreshold);
                vec = Vector256.Subtract(vec, mask);
                Vector256.StoreUnsafe(vec, ref start, (nuint)i);
            }
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<int>.Count)
        {
            var vThreshold = Vector128.Create(threshold);
            ref int start = ref MemoryMarshal.GetReference(data);

            int lastVector = data.Length - Vector128<int>.Count;
            for (; i <= lastVector; i += Vector128<int>.Count)
            {
                var vec = Vector128.LoadUnsafe(ref start, (nuint)i);
                var mask = Vector128.GreaterThan(vec, vThreshold);
                vec = Vector128.Subtract(vec, mask);
                Vector128.StoreUnsafe(vec, ref start, (nuint)i);
            }
        }

        // Scalar tail
        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

